import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


_cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAException.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cstdint>

namespace {

  constexpr int TILE = 64;
  constexpr int TILE_K = 32;

__device__ __forceinline__ void async_copy_16(float* dst, const float* src, int valid_bytes) {
#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 800)
    const bool aligned =
        valid_bytes == 16 &&
        ((reinterpret_cast<uintptr_t>(dst) & 0xF) == 0) &&
        ((reinterpret_cast<uintptr_t>(src) & 0xF) == 0);
    if (aligned) {
        asm volatile(
            "cp.async.ca.shared.global [%0], [%1], 16, 16;"
            :
            : "r"(static_cast<unsigned int>(
                    __cvta_generic_to_shared(dst))),
              "l"(src)
        );
        return;
    }
#endif
    const int valid_floats = valid_bytes / sizeof(float);
    #pragma unroll
    for (int i = 0; i < 4; ++i) {
        dst[i] = (i < valid_floats) ? src[i] : 0.0f;
    }
}

__device__ __forceinline__ void async_commit() {
#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 800)
    asm volatile("cp.async.commit_group;");
#endif
}

__device__ __forceinline__ void async_wait() {
#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 800)
    asm volatile("cp.async.wait_group 0;");
#endif
}

__global__ void matmul_kernel(
    const float* __restrict__ A,
    const float* __restrict__ B,
    float* __restrict__ C,
    int M,
    int K,
    int N,
    bool vec_a,
    bool vec_b,
    bool vec_c
) {
    __shared__ float As[2][TILE][TILE_K + 16];
    __shared__ float Bs[2][TILE_K][TILE];
    const int tid = threadIdx.x;
    const int row_base = blockIdx.y * TILE + (tid >> 4) * 4;
    const int col_base = blockIdx.x * TILE + (tid & 15) * 4;
    float acc[4][4];

    #pragma unroll
    for (int r = 0; r < 4; ++r) {
        #pragma unroll
        for (int q = 0; q < 4; ++q) {
            acc[r][q] = 0.0f;
        }
    }

    const int tiles = (K + TILE_K - 1) / TILE_K;
    int cur = 0;

    for (int idx4 = tid * 4; idx4 < TILE * TILE_K; idx4 += 256 * 4) {
        const int smem_row = idx4 / TILE_K;
        const int smem_col = idx4 - smem_row * TILE_K;
        const int a_row = blockIdx.y * TILE + smem_row;
        const int a_col = smem_col;
        const int a_valid = (a_row < M && a_col < K) ? min(16, (K - a_col) * 4) : 0;
        const float* a_src = (a_valid > 0) ? (A + a_row * K + a_col) : A;
        async_copy_16(&As[cur][smem_row][smem_col], a_src, a_valid);
    }

    for (int idx4 = tid * 4; idx4 < TILE_K * TILE; idx4 += 256 * 4) {
        const int smem_row = idx4 / TILE;
        const int smem_col = idx4 - smem_row * TILE;
        const int b_row = smem_row;
        const int b_col = blockIdx.x * TILE + smem_col;
        const int b_valid = (b_row < K && b_col < N) ? min(16, (N - b_col) * 4) : 0;
        const float* b_src = (b_valid > 0) ? (B + b_row * N + b_col) : B;
        async_copy_16(&Bs[cur][smem_row][smem_col], b_src, b_valid);
    }
    async_commit();
    async_wait();
    __syncthreads();

    for (int tile = 0; tile < tiles; ++tile) {
        const int next = cur ^ 1;

        if (tile + 1 < tiles) {
            for (int idx4 = tid * 4; idx4 < TILE * TILE_K; idx4 += 256 * 4) {
                const int smem_row = idx4 / TILE_K;
                const int smem_col = idx4 - smem_row * TILE_K;
                const int a_row = blockIdx.y * TILE + smem_row;
                const int a_col = (tile + 1) * TILE_K + smem_col;
                const int a_valid = (a_row < M && a_col < K) ? min(16, (K - a_col) * 4) : 0;
                const float* a_src = (a_valid > 0) ? (A + a_row * K + a_col) : A;
                async_copy_16(&As[next][smem_row][smem_col], a_src, a_valid);
            }

            for (int idx4 = tid * 4; idx4 < TILE_K * TILE; idx4 += 256 * 4) {
                const int smem_row = idx4 / TILE;
                const int smem_col = idx4 - smem_row * TILE;
                const int b_row = (tile + 1) * TILE_K + smem_row;
                const int b_col = blockIdx.x * TILE + smem_col;
                const int b_valid = (b_row < K && b_col < N) ? min(16, (N - b_col) * 4) : 0;
                const float* b_src = (b_valid > 0) ? (B + b_row * N + b_col) : B;
                async_copy_16(&Bs[next][smem_row][smem_col], b_src, b_valid);
            }
            async_commit();
        }

        #pragma unroll
        for (int k = 0; k < TILE_K; ++k) {
            float a[4];
            #pragma unroll
            for (int r = 0; r < 4; ++r) {
                a[r] = As[cur][(tid >> 4) * 4 + r][k];
            }
            #pragma unroll
            for (int q = 0; q < 4; ++q) {
                const float b = Bs[cur][k][(tid & 15) * 4 + q];
                #pragma unroll
                for (int r = 0; r < 4; ++r) {
                    acc[r][q] = fmaf(a[r], b, acc[r][q]);
                }
            }
        }

        if (tile + 1 < tiles) {
            async_wait();
            __syncthreads();
            cur = next;
        }
    }

    #pragma unroll
    for (int r = 0; r < 4; ++r) {
        const int row = row_base + r;
        const int col = col_base;
        if (row < M && vec_c && col + 3 < N) {
            const float4 v = make_float4(acc[r][0], acc[r][1], acc[r][2], acc[r][3]);
            *reinterpret_cast<float4*>(C + row * N + col) = v;
        } else if (row < M) {
            #pragma unroll
            for (int q = 0; q < 4; ++q) {
                const int out_col = col + q;
                if (out_col < N) {
                    C[row * N + out_col] = acc[r][q];
                }
            }
        }
    }
}

} // namespace

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda(), "A must be a CUDA tensor");
    TORCH_CHECK(B.is_cuda(), "B must be a CUDA tensor");
    TORCH_CHECK(A.scalar_type() == torch::kFloat32, "A must be float32");
    TORCH_CHECK(B.scalar_type() == torch::kFloat32, "B must be float32");
    TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "A and B must be 2D tensors");
    TORCH_CHECK(A.size(1) == B.size(0), "Incompatible matrix dimensions");

    TORCH_CHECK(A.device() == B.device(),
                "A and B must be on the same CUDA device");
    auto A_contig = A.contiguous();
    auto B_contig = B.contiguous();

    const int M = static_cast<int>(A_contig.size(0));
    const int K = static_cast<int>(A_contig.size(1));
    const int N = static_cast<int>(B_contig.size(1));

    auto C = torch::empty({M, N}, A_contig.options());

    const bool vec_a =
        ((K & 3) == 0) &&
        ((reinterpret_cast<uintptr_t>(A_contig.data_ptr<float>()) & 0xF) == 0);
    const bool vec_b =
        ((N & 3) == 0) &&
        ((reinterpret_cast<uintptr_t>(B_contig.data_ptr<float>()) & 0xF) == 0);
    const bool vec_c =
        ((N & 3) == 0) &&
        ((reinterpret_cast<uintptr_t>(C.data_ptr<float>()) & 0xF) == 0);
    const dim3 block(256);
    const dim3 grid(
        (N + TILE - 1) / TILE,
        (M + TILE - 1) / TILE
    );

    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    matmul_kernel<<<grid, block, 0, stream>>>(
        A_contig.data_ptr<float>(),
        B_contig.data_ptr<float>(),
        C.data_ptr<float>(),
        M,
        K,
        N,
        vec_a,
        vec_b,
        vec_c

    );
    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return C;
}
"""

_cpp_src = r"""
#include <torch/extension.h>

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B);
"""

_matmul_ext = load_inline(
    name="custom_cuda_matmul_extension",
    cpp_sources=_cpp_src,
    cuda_sources=_cuda_src,
    functions=["matmul_cuda"],
    extra_cuda_cflags=["-O3", "--use_fast_math"],
    extra_cflags=["-O3"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return _matmul_ext.matmul_cuda(A, B)

